/* DOM.RENDER photo assets bundle — approved sketch preview + photographic selection thumbnails. */
(function() {
'use strict';
window.DOM_RENDER_ASSETS = window.DOM_RENDER_ASSETS || {};
const approvedSketch = 'data:image/webp;base64,';
window.DOM_RENDER_ASSETS['assets/residence-model-sketch.jpg'] = approvedSketch;
const atlas = 'data:image/webp;base64,';
const names = ["assets/thumbs/env-city.jpg", "assets/thumbs/env-coast.jpg", "assets/thumbs/env-courtyard.jpg", "assets/thumbs/env-forest.jpg", "assets/thumbs/env-garden.jpg", "assets/thumbs/env-lake.jpg", "assets/thumbs/env-minimal.jpg", "assets/thumbs/env-mist.jpg", "assets/thumbs/env-mountains.jpg", "assets/thumbs/env-nordic.jpg", "assets/thumbs/look-cinematic.jpg", "assets/thumbs/look-dusk.jpg", "assets/thumbs/look-fog.jpg", "assets/thumbs/look-noon.jpg", "assets/thumbs/look-original.jpg", "assets/thumbs/look-winter.jpg", "assets/thumbs/mat-brick.jpg", "assets/thumbs/mat-ceramic.jpg", "assets/thumbs/mat-concrete.jpg", "assets/thumbs/mat-glass.jpg", "assets/thumbs/mat-limestone.jpg", "assets/thumbs/mat-metal.jpg", "assets/thumbs/mat-plaster.jpg", "assets/thumbs/mat-travertine.jpg", "assets/thumbs/mat-wood.jpg", "assets/thumbs/plants-decorative.jpg", "assets/thumbs/plants-forest.jpg", "assets/thumbs/plants-mediterranean.jpg", "assets/thumbs/plants-minimal.jpg", "assets/thumbs/plants-tropical.jpg", "assets/thumbs/season-autumn.jpg", "assets/thumbs/season-spring.jpg", "assets/thumbs/season-summer.jpg", "assets/thumbs/season-winter.jpg", "assets/thumbs/time-day.jpg", "assets/thumbs/time-golden.jpg", "assets/thumbs/time-morning.jpg", "assets/thumbs/time-night.jpg", "assets/thumbs/weather-clear.jpg", "assets/thumbs/weather-cloud.jpg", "assets/thumbs/weather-fog.jpg", "assets/thumbs/weather-rain.jpg", "assets/thumbs/weather-snow.jpg"];
const positions = new Map(names.map((name,index)=>[name,index]));
const transparentPixel = 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';
function applyPhotoThumb(img, path) {
  const idx=positions.get(path);
  if(idx===undefined || img.dataset.domPhotoApplied==='1') return false;
  img.dataset.domPhotoApplied='1';
  const col=idx%9, row=Math.floor(idx/9);
  img.src=transparentPixel;
  img.style.backgroundImage='url("'+atlas+'")';
  img.style.backgroundRepeat='no-repeat';
  img.style.backgroundSize='900% 500%';
  img.style.backgroundPosition=(col/(9-1)*100)+'% '+(row/(5-1)*100)+'%';
  img.style.backgroundColor='#deded8';
  return true;
}
document.addEventListener('error',function(event){
  const img=event.target;
  if(!(img instanceof HTMLImageElement))return;
  const src=(img.getAttribute('src')||'').split('?')[0];
  if(positions.has(src)) {
    applyPhotoThumb(img,src);
    event.stopImmediatePropagation();
  }
},true);
document.addEventListener('DOMContentLoaded',function(){
  const before=document.getElementById('beforeImg');
  if(before)before.src=approvedSketch;
});
})();